def is_balanced(s: str) -> bool:
    """
    Return True if every bracket in s among (), [] and {} is correctly matched and nested.
    Characters that are not brackets are ignored.
    """
    stack = []
    for c in s:
        if c in "([{":
            stack.append(c)
        elif c in ")]}":
            if not stack:
                return False
            if c == ")" and stack.pop() != "(":
                return False
            if c == "]" and stack.pop() != "[":
                return False
            if c == "}" and stack.pop() != "{":
                return False
    return not stack
