def caesar(s: str, k: int) -> str:
    """
    Shift every letter in s forward by k positions in the alphabet.
    Wrap around and preserve case.
    k may be negative or larger than 26.
    Non-letters are unchanged.
    """
    result = []
    for c in s:
        if c.islower():
            result.append(chr((ord(c) - ord('a') + k) % 26 + ord('a')))
        elif c.isupper():
            result.append(chr((ord(c) - ord('A') + k) % 26 + ord('A')))
        else:
            result.append(c)
    return ''.join(result)
